//2bit
#define black   0x00  /// 00
#define white   0x01  /// 01
#define yellow  0x02  /// 10
#define red     0x03  /// 11


#define Source_BITS     88
#define Gate_BITS   184
#define ALLSCREEN_BYTES   4048


//EPD
void EPD_init(void);
